#ifdef I2S_HAVE_RX
static void i2s_rx_schedule(struct esp32s3_i2s_s *priv,
                            struct esp32s3_dmadesc_s *inlink)
{
  struct esp32s3_buffer_s *bfcontainer;
  struct esp32s3_dmadesc_s *bfdesc;
  int ret;
  static int rxdbg_sched_count;

  /* Upon entry, the transfer(s) that just completed are the ones in the
   * priv->rx.act queue.
   */

  /* Move all entries from the rx.act queue to the rx.done queue */

  if (!sq_empty(&priv->rx.act))
    {
      /* Remove the next buffer container from the rx.act list */

      bfcontainer = (struct esp32s3_buffer_s *)sq_peek(&priv->rx.act);

      /* Find the last descriptor of the current buffer container */

      bfdesc = bfcontainer->dma_link;

      /* The RX successful-EOF interrupt reports the final descriptor in
       * the chain.  Intermediate RX descriptors do not carry EOF, so walk
       * the complete chain instead of stopping at the first non-EOF link.
       */

      while (bfdesc->next != NULL)
        {
          bfdesc = bfdesc->next;
        }

      if (rxdbg_sched_count < 8)
        {
          printf("[i2s-rx] schedule in=%p last=%p act=%p\n",
                 inlink, bfdesc, bfcontainer);
          rxdbg_sched_count++;
        }

      if (bfdesc == inlink)
        {
          sq_remfirst(&priv->rx.act);

          /* Report the result of the transfer */

          bfcontainer->result = OK;

          /* Add the completed buffer container to the tail of the rx.done
           * queue
           */

          sq_addlast((sq_entry_t *)bfcontainer, &priv->rx.done);

          /* Let the RX worker return the completed buffer to the audio
           * upper half before starting the next capture.  Starting the next
           * DMA directly from the interrupt can keep the CPU in an IRQ loop
           * long enough that the worker never gets to drain rx.done.
           */
        }

      /* If the worker has completed running, then reschedule the working
       * thread.
       */

      if (work_available(&priv->rx.work))
        {
          /* Schedule the RX DMA done processing to occur on the worker
           * thread.
           */

          ret = work_queue(I2S_RXWORK, &priv->rx.work, i2s_rx_worker,
                           priv, 0);
          if (rxdbg_sched_count < 8)
            {
              printf("[i2s-rx] work_queue ret=%d\n", ret);
              rxdbg_sched_count++;
            }
          if (ret != 0)
            {
              i2serr("ERROR: Failed to queue RX work: %d\n", ret);
            }
        }
    }
}
#endif /* I2S_HAVE_RX */

