#ifdef I2S_HAVE_RX
static int i2s_receive(struct i2s_dev_s *dev, struct ap_buffer_s *apb,
                       i2s_callback_t callback, void *arg, uint32_t timeout)
{
  struct esp32s3_i2s_s *priv = (struct esp32s3_i2s_s *)dev;
  static int rxdbg_receive_count;

  if (priv->config->rx_en)
    {
      struct esp32s3_buffer_s *bfcontainer;
      int ret = OK;
      uint32_t nbytes;
      uint32_t nsamp;

      /* Check max audio buffer data size from the upper half and align the
       * receiving buffer according to the data width.
       */

      nbytes = MIN(apb->nmaxbytes, ESP32S3_DMA_BUFLEN_MAX);

      /* RX EOF must fall on a complete audio sample.  The GDMA maximum is
       * 4095 bytes, which is not aligned for 16/32-bit PCM; align after
       * applying that hardware limit (4092 bytes for 32-bit input).
       */

      nbytes -= (nbytes % (priv->data_width / 8));

      if (rxdbg_receive_count < 8)
        {
          printf("[i2s-rx] receive nmax=%" PRIu32 " nbytes=%" PRIu32
                 " width=%u started=%d\n",
                 apb->nmaxbytes,
                 nbytes,
                 priv->data_width,
                 priv->rx_started);
          rxdbg_receive_count++;
        }

      /* Allocate a buffer container in advance */

      bfcontainer = i2s_buf_allocate(priv);
      if (bfcontainer == NULL)
        {
          i2serr("Failed to allocate the buffer container");
          return -ENOMEM;
        }

      /* Get exclusive access to the I2S driver data */

      ret = nxmutex_lock(&priv->lock);
      if (ret < 0)
        {
          goto errout_with_buf;
        }

      /* Add a reference to the audio buffer */

      apb_reference(apb);

      /* Initialize the buffer container structure */

      bfcontainer->callback = callback;
      bfcontainer->timeout  = timeout;
      bfcontainer->arg      = arg;
      bfcontainer->apb      = apb;
      bfcontainer->nbytes   = nbytes;
      bfcontainer->result   = -EBUSY;

      ret = i2s_rxdma_setup(priv, bfcontainer);

      if (ret != OK)
        {
          goto errout_with_buf;
        }

      i2sinfo("Prepared %d bytes to receive DMA buffers\n", apb->nmaxbytes);
      i2s_dump_buffer("Audio pipeline buffer:", &apb->samp[apb->curbyte],
                      apb->nbytes - apb->curbyte);

      nxmutex_unlock(&priv->lock);

      return OK;

errout_with_buf:
      nxmutex_unlock(&priv->lock);
      i2s_buf_free(priv, bfcontainer);
      return ret;
    }

  return -ENOTTY;
}
#endif /* I2S_HAVE_RX */

/****************************************************************************
 * Name: i2s_ioctl
 *
 * Description:
 *   Implement the lower-half logic ioctl commands
 *
 * Input parameters:
 *   dev - A reference to the lower-half I2S driver device
 *   cmd - The ioctl command
 *   arg - The argument accompanying the ioctl command
 *
 * Returned Value:
 *   OK on success; A negated errno value on failure.
 *
 ****************************************************************************/

static int i2s_ioctl(struct i2s_dev_s *dev, int cmd, unsigned long arg)
{
  struct esp32s3_i2s_s *priv = (struct esp32s3_i2s_s *)dev;
  struct audio_buf_desc_s  *bufdesc;
  struct ap_buffer_info_s  *bufinfo;
  int ret = -ENOTTY;

  switch (cmd)
    {
      /* AUDIOIOC_START - Start the audio stream.
       *
       *   ioctl argument:  Audio session
       */

      case AUDIOIOC_START:
        {
          printf("[i2s-rx] AUDIOIOC_START streaming=1\n");
          i2sinfo("AUDIOIOC_START\n");

          priv->streaming = true;

#ifdef I2S_HAVE_RX
          if (priv->config->rx_en && !priv->rx_started)
            {
              irqstate_t flags;

              i2s_rx_channel_start(priv);
              flags = spin_lock_irqsave(&priv->slock);
              i2s_rxdma_start(priv);
              spin_unlock_irqrestore(&priv->slock, flags);
            }
#endif

          ret = OK;
        }
        break;

      /* AUDIOIOC_STOP - Stop the audio stream.
       *
       *   ioctl argument:  Audio session
       */

#ifndef CONFIG_AUDIO_EXCLUDE_STOP
      case AUDIOIOC_STOP:
        {
          printf("[i2s-rx] AUDIOIOC_STOP streaming=0\n");
          i2sinfo("AUDIOIOC_STOP\n");

          priv->streaming = false;

#ifdef I2S_HAVE_RX
          if (priv->config->rx_en)
            {
              struct esp32s3_buffer_s *bfcontainer;
              irqstate_t flags;
              int workret;

              /* Stop the hardware first, then reclaim every buffer held by
               * the RX lower half.  NxRecorder waits for a FINAL dequeue
               * before it can finish nxrecorder_stop().
               */

              i2s_rx_channel_stop(priv);

              flags = spin_lock_irqsave(&priv->slock);
              while ((bfcontainer =
                      (struct esp32s3_buffer_s *)sq_remfirst(&priv->rx.act))
                     != NULL)
                {
                  bfcontainer->result = -ECANCELED;
                  sq_addlast((sq_entry_t *)bfcontainer, &priv->rx.done);
                }

              while ((bfcontainer =
                      (struct esp32s3_buffer_s *)sq_remfirst(&priv->rx.pend))
                     != NULL)
                {
                  bfcontainer->result = -ECANCELED;
                  sq_addlast((sq_entry_t *)bfcontainer, &priv->rx.done);
                }

              spin_unlock_irqrestore(&priv->slock, flags);

              /* The audio upper half holds its lock while invoking STOP.
               * Dequeue asynchronously after this ioctl returns; waiting
               * for or directly running the worker here would deadlock when
               * its callback tries to enter the upper half.
               */

              /* Use a separate work item so STOP completion cannot be lost
               * in the small window where the normal RX worker is exiting
               * but still reports itself busy.
               */

              workret = work_queue(I2S_RXWORK, &priv->rx_stop_work,
                                   i2s_rx_worker, priv, 0);
              if (workret != OK)
                {
                  i2serr("ERROR: Failed to queue RX stop work: %d\n",
                         workret);
                }
            }
#endif

          ret = OK;

