       * also modified from the interrupt level.
       */

      flags = spin_lock_irqsave(&priv->slock);
      bfcontainer = (struct esp32s3_buffer_s *)sq_remfirst(&priv->rx.done);
      spin_unlock_irqrestore(&priv->slock, flags);

      if (bfcontainer == NULL)
        {
          break;
        }

      if (rxdbg_worker_count < 8)
        {
          printf("[i2s-rx] worker result=%d streaming=%d\n",
                 bfcontainer->result,
                 priv->streaming);
          rxdbg_worker_count++;
        }

      dmadesc = bfcontainer->dma_link;

      bfcontainer->apb->nbytes = 0;

      /* RX descriptors get their data length from hardware.  Only the
       * descriptor that terminates the peripheral frame is guaranteed to
       * carry EOF, so do not use EOF as the condition for counting bytes.
       */

      while (dmadesc != NULL)
        {
          bfcontainer->apb->nbytes +=
              (dmadesc->ctrl >> ESP32S3_DMA_CTRL_DATALEN_S) &
              ESP32S3_DMA_CTRL_DATALEN_V;
          dmadesc = dmadesc->next;
        }

      /* Perform the RX transfer done callback */

      DEBUGASSERT(bfcontainer && bfcontainer->callback);

      if (priv->streaming == false)
        {
          bfcontainer->apb->flags |= AUDIO_APB_FINAL;
        }

