/****************************************************************************
 * Name: nxrecorder_stop
 *
 *   nxrecorder_stop() stops the current recordback and closes the file and
 *   the associated device.
 *
 * Input:
 *   precorder    Pointer to the initialized MRecorder context
 *
 ****************************************************************************/

#ifndef CONFIG_AUDIO_EXCLUDE_STOP
int nxrecorder_stop(FAR struct nxrecorder_s *precorder)
{
  struct audio_msg_s term_msg;
  struct mq_attr oldattr;
  struct mq_attr newattr;
  bool restore_mqattr = false;
  int retry;
  int ret;

  DEBUGASSERT(precorder != NULL);

  /* Validate we are not in IDLE state */

  pthread_mutex_lock(&precorder->mutex);
  if (precorder->state == NXRECORDER_STATE_IDLE)
    {
      pthread_mutex_unlock(&precorder->mutex);
      return OK;
    }

  pthread_mutex_unlock(&precorder->mutex);

  /* Stop the device from the controlling thread before queuing the recorder
   * STOP message.  Capture devices can otherwise keep filling the user queue
   * with DEQUEUE messages fast enough that a normal STOP command never gets
   * serviced promptly.
   */

#ifdef CONFIG_AUDIO_MULTI_SESSION
  ioctl(precorder->dev_fd, AUDIOIOC_STOP, (uintptr_t)precorder->session);
#else
  ioctl(precorder->dev_fd, AUDIOIOC_STOP, 0);
#endif

  /* Notify the recordback thread that it needs to cancel the recordback */

  term_msg.msg_id = AUDIO_MSG_STOP;
  term_msg.u.data = 0;

  if (mq_getattr(precorder->mq, &oldattr) == OK)
    {
      newattr = oldattr;
      newattr.mq_flags |= O_NONBLOCK;
      restore_mqattr = mq_setattr(precorder->mq, &newattr, NULL) == OK;
    }

  for (retry = 0; retry < 100; retry++)
    {
      ret = mq_send(precorder->mq, (FAR const char *)&term_msg,
                    sizeof(term_msg), CONFIG_NXRECORDER_MSG_PRIO);
      if (ret == OK)
        {
          break;
        }

      if (errno != EAGAIN)
        {
          break;
        }

      usleep(10000);
    }

  if (restore_mqattr)
    {
      mq_setattr(precorder->mq, &oldattr, NULL);
    }

  if (ret < 0)
    {
      return -errno;
    }

  /* Join the thread.  The thread will do all the cleanup. */

  nxrecorder_jointhread(precorder);

  return OK;
