 * Name: nxrecorder_writebuffer
 *
 *  Write the next block of data to the pcm raw data file into the specified
 *  buffer.
 *
 ****************************************************************************/

static int nxrecorder_writebuffer(FAR struct nxrecorder_s *precorder,
                                  FAR struct ap_buffer_s *apb)
{
  uint32_t remaining;
  uint32_t original_nbytes;
  static int record_dbg_count;
  int ret;

  /* Validate the file is still open.  It will be closed automatically when
   * we encounter the end of file (or, perhaps, a write error that we cannot
   * handle.
   */

  if (precorder->fd == -1)
    {
      /* Return -ENODATA to indicate that there is nothing more to write to
       * the file.
       */

      return -ENODATA;
    }

  if (precorder->record_limit_bytes > 0)
    {
      if (precorder->record_bytes >= precorder->record_limit_bytes)
        {
          return -ENODATA;
        }

      remaining = precorder->record_limit_bytes - precorder->record_bytes;
      if (apb->nbytes > remaining)
        {
          apb->nbytes = remaining;
        }
    }

  original_nbytes = apb->nbytes;

  /* Write data to the file. */

  ret = precorder->ops->write_data(precorder->fd, apb);
  if (record_dbg_count < 12)
    {
      printf("[nxrecorder] writebuffer nbytes=%" PRIu32
             " ret=%d before=%" PRIu32 " limit=%" PRIu32 "\n",
             original_nbytes,
             ret,
             precorder->record_bytes,
             precorder->record_limit_bytes);
      record_dbg_count++;
    }

  if (ret < 0)
    {
      return ret;
    }

  precorder->record_bytes += original_nbytes;

  apb->curbyte = 0;
  apb->flags   = 0;

  if (precorder->record_limit_bytes > 0 &&
      precorder->record_bytes >= precorder->record_limit_bytes)
