static int i2s_rxdma_start(struct esp32s3_i2s_s *priv)
{
  struct esp32s3_buffer_s *bfcontainer;
  size_t eof_nbytes;
  static int rxdbg_start_count;

  /* Buffers may be queued before AUDIOIOC_START when reopening the audio
   * device.  Leave them pending until the RX channel and its IRQ have been
   * restarted.
   */

  if (!priv->rx_started)
    {
      if (rxdbg_start_count < 8)
        {
          printf("[i2s-rx] start defer: rx_started=0 pend_empty=%d\n",
                 sq_empty(&priv->rx.pend));
          rxdbg_start_count++;
        }

      return OK;
    }

  /* If there is already an active transmission in progress, then bail
   * returning success.
   */

  if (!sq_empty(&priv->rx.act))
    {
      return OK;
    }

  /* If there are no pending transfer, then bail returning success */

  if (sq_empty(&priv->rx.pend))
    {
      return OK;
    }

  bfcontainer = (struct esp32s3_buffer_s *)sq_remfirst(&priv->rx.pend);

  /* If there isn't already an active transmission in progress,
   * then start it.
   */

  eof_nbytes = MIN(bfcontainer->nbytes, ESP32S3_DMA_BUFLEN_MAX);

  modifyreg32(I2S_RXEOF_NUM_REG(priv->config->port), I2S_RX_EOF_NUM_M,
              FIELD_TO_VALUE(I2S_RX_EOF_NUM, eof_nbytes));

  esp32s3_dma_load(bfcontainer->dma_link, priv->dma_channel, I2S_RX);
  esp32s3_dma_enable(priv->dma_channel, I2S_RX);

  modifyreg32(I2S_RX_CONF_REG(priv->config->port), 0, I2S_RX_START);

  sq_addlast((sq_entry_t *)bfcontainer, &priv->rx.act);

  if (rxdbg_start_count < 8)
    {
      printf("[i2s-rx] dma_start port=%d ch=%" PRIu32
             " nbytes=%" PRIu32 " eof=%u rx_conf=%08" PRIx32 "\n",
             priv->config->port,
             priv->dma_channel,
             bfcontainer->nbytes,
             (unsigned int)eof_nbytes,
             getreg32(I2S_RX_CONF_REG(priv->config->port)));
      rxdbg_start_count++;
    }

  return OK;

