+static int parse_voice_ai_seconds(int argc, char *argv[], long *seconds)
+{
+  int value_seen = 0;
+  int i;
+
+  *seconds = BLIND_BADGE_VOICE_AI_DEFAULT_SECONDS;
+
+  for (i = 2; i < argc; i++)
+    {
+      char *end;
+      long value;
