557	                          size_t *pcm_len_out)
558	{
559	  size_t max_samples = (size_t)seconds * 16000;
560	  size_t pcm_cap = max_samples * sizeof(int16_t);
561	  int16_t samples[256];
562	  int16_t *pcm16;
563	  FILE *stream;
564	  size_t total = 0;
565	  size_t count;
566	  int32_t peak16 = 0;
567	
568	  *pcm_out = NULL;
569	  *pcm_len_out = 0;
570	
571	  pcm16 = malloc(pcm_cap);
572	  if (pcm16 == NULL)
573	    {
574	      return -ENOMEM;
575	    }
576	
577	  stream = fopen(path, "rb");
578	  if (stream == NULL)
579	    {
580	      free(pcm16);
581	      return -errno;
582	    }
583	
584	  while (total < max_samples &&
585	         (count = fread(samples, sizeof(samples[0]),
586	                        sizeof(samples) / sizeof(samples[0]), stream)) > 0)
587	    {
588	      size_t i;
589	
590	      for (i = 0; i < count && total < max_samples; i++)
591	        {
592	          int16_t sample = samples[i];
593	          int32_t magnitude = sample < 0 ? -(int32_t)sample :
594	                                           (int32_t)sample;
595	
596	          pcm16[total++] = sample;
597	          if (magnitude > peak16)
598	            {
599	              peak16 = magnitude;
600	            }
601	        }
602	    }
603	
604	  fclose(stream);
605	
606	  if (total == 0)
607	    {
608	      free(pcm16);
609	      return -ENODATA;
610	    }

