static void cmd_set_wifi(int argc, char** argv)
{
    if (argc < 3) {
        printf("Usage: set_wifi <ssid> <REDACTED_WIFI_PASSWORD>\n");
        return;
    }
    printf("Connecting to '%s' ...\n", argv[1]);
    int err = network_wifi_connect(NULL, argv[1], argv[2]);
    if (err == OK)
        printf("WiFi connected: %s\n", network_get_ip());
    else
        printf("WiFi failed. Check SSID/password or run net_status.\n");
}

int ai_agent_wifi_reconnect(void)
{
    int err;

    /* A build-local configuration is the authoritative boot configuration.
     * Trying stale persisted credentials first can double the boot timeout. */
    if (AI_AGENT_LOCAL_WIFI_SSID[0] != '\0') {
        return network_wifi_connect_boot(NULL, AI_AGENT_LOCAL_WIFI_SSID,
            AI_AGENT_LOCAL_WIFI_PASSWORD);
    }

    /* Persisted credentials require the config store.  Keep this off the
     * compile-time local credential path so physical reset can start Wi-Fi
     * immediately even when storage initialization is slow. */
    config_store_init();
    err = network_wifi_reconnect();
    return err;
}

static void cmd_wifi_reconnect(void)
{
    printf("Reconnecting WiFi ...\n");
    int err = ai_agent_wifi_reconnect();
    if (err == OK)
        printf("Reconnected: %s\n", network_get_ip());
    else if (err == ERROR)
        printf("WiFi reconnect failed. Check local or saved credentials.\n");
    else
        printf("WiFi reconnect failed.\n");
}

#ifdef CONFIG_AI_AGENT_NET_RPMSG
static void cmd_net_reconnect(void)
{
    printf("Reconnecting...\n");
    int ret = network_reconnect();
    printf("Reconnect %s\n", ret == OK ? "triggered" : "failed");

